#: MURaM magnetic corrections Δw (added to w), [M/H] = 0 MURaM stars; linear in
#: Teff, clamped outside 3196-6807 K, applied at all log g and [M/H]
#: (an extrapolation); MURaM ratios held constant below mu = 0.1.
_CORR_TEFF = np.array([3196.0, 3518.0, 3707.0, 4543.0, 5240.0, 5778.0, 6807.0])
_CORR = {
    "ssd": [[5.900000e-05, 3.300000e-05, -5.900000e-05, 1.280000e-04], [4.610000e-04, 1.062000e-03, -1.142000e-03, 1.410000e-04], [-2.900000e-04, 3.320000e-04, -9.320000e-04, -3.056000e-03], [4.900000e-05, 4.600000e-05, -7.790000e-04, -8.500000e-04], [-5.500000e-04, -1.797000e-03, 3.560000e-04, 1.205000e-03], [-1.569000e-03, -8.170000e-04, 1.557000e-03, -6.180000e-04], [-6.580000e-04, 5.920000e-03, 3.163000e-03, -9.546000e-03]],
    "B100G": [[-2.150000e-04, 6.090000e-04, -2.230000e-04, -1.262000e-03], [1.710000e-04, 1.484000e-03, -4.820000e-04, -1.313000e-03], [-1.140000e-03, -5.380000e-04, 1.983000e-03, -3.824000e-03], [-9.470000e-04, -4.481000e-03, 2.628000e-03, 1.263000e-03], [-2.715000e-03, -1.211600e-02, 6.534000e-03, 3.255000e-03], [-4.841000e-03, -1.046500e-02, 9.638000e-03, -3.471000e-03], [-7.548000e-03, -1.242800e-02, 2.375400e-02, -9.115000e-03]],
    "B200G": [[-3.910000e-04, 1.822000e-03, -1.005000e-03, -3.321000e-03], [-1.910000e-04, 2.277000e-03, -1.106000e-03, -4.296000e-03], [-2.519000e-03, -6.750000e-04, 2.574000e-03, -7.744000e-03], [-3.045000e-03, -9.193000e-03, 6.945000e-03, -6.140000e-04], [-6.868000e-03, -1.940700e-02, 1.401300e-02, -2.489000e-03], [-9.179000e-03, -2.277400e-02, 1.894600e-02, -3.474000e-03], [-1.445900e-02, -2.572000e-02, 4.485600e-02, -2.486900e-02]],
    "B300G": [[-5.470000e-04, 2.602000e-03, -1.853000e-03, -4.978000e-03], [-7.980000e-04, 3.563000e-03, -1.712000e-03, -6.221000e-03], [-3.249000e-03, -1.730000e-04, 2.092000e-03, -1.111500e-02], [-5.768000e-03, -1.465300e-02, 1.013200e-02, -1.812000e-03], [-1.165400e-02, -3.046900e-02, 2.179000e-02, -3.850000e-03], [-1.388000e-02, -2.463700e-02, 3.018400e-02, -2.274300e-02], [-2.383400e-02, -3.245400e-02, 7.714300e-02, -6.440200e-02]],
}


def _unpack(s, shape, dtype):
    return np.frombuffer(zlib.decompress(base64.b64decode(s)), dtype).astype(float).reshape(shape)


_X = _unpack(_GRID, (_N, 3), "<f8") / SCALE
_Y = _unpack(_DATA, (_N, 6), "<f4")
_LIN = LinearNDInterpolator(_X, _Y)
_NEAR = None


def _pole(mu, e):
    return ((mu * mu + e) ** -2 - (1 + e) ** -2) / (e ** -2 - (1 + e) ** -2)


def shapes(mu):
    """T_j(mu), shape (len(mu), 4)."""
    mu = np.asarray(mu, float)
    return np.stack([1 - mu ** 4, (1 - mu ** 2) ** 2, _pole(mu, EPS[0]), _pole(mu, EPS[1])], axis=-1)


def intensity(w, mu):
    """I(mu)/I(1) for hybrid4 weights w."""
    return 1 - shapes(mu) @ np.asarray(w, float)


def is_physical(w, n=2001):
    """Positive and non-increasing towards the limb on a dense grid."""
    I = intensity(w, np.linspace(0.0, 1.0, n))
    return bool(I[0] >= -1e-10 and np.all(np.diff(I) >= -1e-10))


def coefficients(teff, logg, mh, extrapolate=False, correction=None):
    """Interpolated hybrid4 weights at (Teff [K], log g [cgs], [M/H]).

    extrapolate=True uses the nearest model outside the grid (else ValueError).
    Returns dict(w, physical, mu_cri, lc_ppm, inside, correction)."""
    global _NEAR
    x = np.array([[teff, logg, mh]]) / SCALE
    y = _LIN(x)[0]
    inside = bool(np.all(np.isfinite(y)))
    if not inside:
        if not extrapolate:
            raise ValueError(f"({teff}, {logg}, {mh}) is outside the {GRID} grid; "
                             "pass extrapolate=True to use the nearest model")
        if _NEAR is None:
            _NEAR = NearestNDInterpolator(_X, _Y)
        y = _NEAR(x)[0]
    w = y[:4].copy()
    if correction is not None:
        if correction not in _CORR:
            raise ValueError(f"correction must be one of {tuple(_CORR)}")
        if not _CORR_TEFF[0] <= teff <= _CORR_TEFF[-1]:
            warnings.warn("Teff outside the MURaM range: correction clamped", stacklevel=2)
        D = np.array(_CORR[correction])
        w = w + np.array([np.interp(teff, _CORR_TEFF, D[:, k]) for k in range(4)])
    return dict(w=tuple(float(v) for v in w), physical=is_physical(w), mu_cri=float(y[4]),
                lc_ppm=float(y[5]), inside=inside, correction=correction)


if __name__ == "__main__":
    import sys
    t, g, m = (float(v) for v in sys.argv[1:4]) if len(sys.argv) >= 4 else (5600.0, 4.4, 0.0)
    r = coefficients(t, g, m, extrapolate=True)
    print(f"hybrid4 {GRID} {BAND} Teff={t:g} logg={g:g} [M/H]={m:+g}: w =",
          " ".join(f"{v:.6f}" for v in r["w"]), "physical" if r["physical"] else "UNPHYSICAL",
          "" if r["inside"] else "(nearest model; outside grid)")
